    double norm_field;
    int new_enabled;
    double excess_val;
    adcs_status_t status;

    /* 1. Null pointer checks for output parameters and inputs */
    if ((momentum == NULL) || (field == NULL) || (enabled == NULL) || 
        (excess == NULL) || (command == NULL) || (torque == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Range and validity checks */
    if (!adcs_is_finite_vec3(momentum) || !adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }
    if (previous_enabled != 0 && previous_enabled != 1) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(start_threshold) || !isfinite(stop_threshold)) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold < 0.0 || stop_threshold >= start_threshold) {
        return ADCS_E_RANGE;
    }

    /* 3. Reset all outputs to zero */
    *enabled = 0;
    *excess = 0.0;
    command->command->x = 0.0;
    command->command->y = 0.0;
    command->command->z = 0.0;
    command->saturated_axes = 0U;
    torque->x = 0.0;
    torque->y = 0.0;
    torque->z = 0.0;

    /* 4. Check for null (zero) momentum or field */
    norm_mom = adcs_vec3_norm(momentum);
    norm_field = adcs_vec3_norm(field);

    if (norm_mom <= ADCS_EPS_NORM || norm_field <= ADCS_EPS_NORM) {
        return ADCS_E_NULL;
    }

    /* 5. Hysteresis State Machine */
    if (!previous_enabled) {
        /* Previous state: Disabled */
        if (norm_mom < start_threshold) {
            /* Stays disabled */
            new_enabled = 0;
            /* Excess basis: max(norm - start, 0) */
            excess_val = (norm_mom > start_threshold) ? (norm_mom - start_threshold) : 0.0;
        } else {
            /* Becomes enabled */
            new_enabled = 1;
            /* Excess basis: norm - stop */
            excess_val = norm_mom - stop_threshold;
        }
    } else {
        /* Previous state: Enabled */
        if (norm_mom <= stop_threshold) {
            /* Becomes disabled */
            new_enabled = 0;
            /* Excess basis: max(norm - start, 0) */
            excess_val = (norm_mom > start_threshold) ? (norm_mom - start_threshold) : 0.0;
        } else {
            /* Stays enabled */
            new_enabled = 1;
            /* Excess basis: norm - stop */
            excess_val = norm_mom - stop_threshold;
        }
    }

    /* 6. Write results */
    *enabled = new_enabled;
    *excess = excess_val;

