    if (new_enabled) {
        status = adcs_momentum_unload_dipole(
            momentum,
            field,
            gain,
            dipole_limit,
            command,
            torque
        );

        if (status != ADCS_OK) {
            /* If failure, outputs remain zero as required, return error */
            return status;
        }
    }

    return ADCS_OK;
