    // 2. Input validation (Range checks)
    if (!adcs_is_finite_vec3(momentum) || !adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }
    if (previous_enabled != 0 && previous_enabled != 1) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(start_threshold) || !isfinite(stop_threshold)) {
        return ADCS_E_RANGE;
    }
    if (stop_threshold < 0.0 || stop_threshold >= start_threshold) {
        return ADCS_E_RANGE;
    }

    // 3. Reset all outputs to zero
    *enabled = 0;
    *excess = 0.0;
    command->command.x = 0.0;
    command->command.y = 0.0;
    command->command.z = 0.0;
    command->saturated_axes = 0U;
    torque->x = 0.0;
    torque->y = 0.0;
    torque->z = 0.0;

    // 4. Calculate momentum norm
    double norm = adcs_vec3_norm(momentum);
    if (!isfinite(norm)) {
        return ADCS_E_RANGE;
    }

    int curr_enabled = 0;
    double current_excess = 0.0;

    // 5. Hysteresis State Machine
    if (previous_enabled == 0) {
        // Previous state: Disabled
        if (norm < start_threshold) {
            // Stay disabled
            curr_enabled = 0;
            current_excess = 0.0; // max(norm - start, 0) is 0 since norm < start
        } else {
            // Transition to Enabled
            curr_enabled = 1;
            current_excess = norm - stop_threshold;

            // Compute bounded magnetic unloading command
            adcs_status_t st = adcs_momentum_unload_dipole(
                momentum, field, gain, dipole_limit, command, torque);

            if (st != ADCS_OK) {
                // On failure, ensure all outputs are zero
                command->command.x = 0.0;
                command->command.y = 0.0;
                command->command.z = 0.0;
                command->saturated_axes = 0U;
                torque->x = 0.0;
                torque->y = 0.0;
                torque->z = 0.0;
                return st;
            }
        }
    } else {
        // Previous state: Enabled
        if (norm <= stop_threshold) {
            // Transition to Disabled
            curr_enabled = 0;
            current_excess = norm - start_threshold;
            if (current_excess < 0.0) {
                current_excess = 0.0;
            }
            // Command and torque remain zero (already reset in step 3)
        } else {
            // Stay Enabled
            curr_enabled = 1;
            current_excess = norm - stop_threshold;

            // Compute bounded magnetic unloading command
            adcs_status_t st = adcs_momentum_unload_dipole(
                momentum, field, gain, dipole_limit, command, torque);

            if (st != ADCS_OK) {
                // On failure, ensure all outputs are zero
                command->command.x = 0.0;
                command->command.y = 0.0;
                command->command.z = 0.0;
                command->saturated_axes = 0U;
                torque->x = 0.0;
                torque->y = 0.0;
                torque->z = 0.0;
                return st;
            }
        }
    }

    // 6. Assign final results
    *enabled = curr_enabled;
    *excess = current_excess;

    return ADCS_OK;
}
